func TestTotal(t *testing.T) {
    for _, tc := range []struct{ name string; in Order; want Decimal }{
        {"no discount", Order{Amount: 3000}, 3000},
        {"ten percent", Order{Amount: 3000, Discount: 0.1}, 2700},
    } {
        t.Run(tc.name, func(t *testing.T) {
            if got := Total(tc.in); got != tc.want {
                t.Fatalf("Total() = %v, want %v", got, tc.want)
            }
        })
    }
}
